nodes.text:
out vec4 fragColor;

uniform vec4 uSphere;   // x = sphere radius, y = pull to the sphere (0..1), z = flow noise scale, w = (free)
uniform vec4 uMotion;   // x = flow strength, y = breathing amount, z = spin speed, w = (free)
uniform vec4 uClock;    // x = time in seconds

// ---------- value noise ----------
float hash13(vec3 p){
    p = fract(p * 0.3183099 + vec3(0.1, 0.2, 0.3));
    p *= 17.0;
    return fract(p.x * p.y * p.z * (p.x + p.y + p.z));
}

float vnoise(vec3 x){
    vec3 i = floor(x);
    vec3 f = fract(x);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(mix(hash13(i),                    hash13(i + vec3(1, 0, 0)), f.x),
                   mix(hash13(i + vec3(0, 1, 0)),    hash13(i + vec3(1, 1, 0)), f.x), f.y),
               mix(mix(hash13(i + vec3(0, 0, 1)),    hash13(i + vec3(1, 0, 1)), f.x),
                   mix(hash13(i + vec3(0, 1, 1)),    hash13(i + vec3(1, 1, 1)), f.x), f.y), f.z);
}

vec3 flow(vec3 p){
    return vec3(vnoise(p),
                vnoise(p + vec3(31.4, 17.7, 5.3)),
                vnoise(p + vec3(-11.2, 7.1, 41.9))) - 0.5;
}

void main(){
    ivec2 idx = ivec2(gl_FragCoord.xy);
    vec4 prev = texelFetch(sTD2DInputs[0], idx, 0);   // positions of the previous frame
    vec4 seed = texelFetch(sTD2DInputs[1], idx, 0);   // tube seed + per particle random

    float rnd = seed.w;
    float t   = uClock.x;

    vec3 p = prev.xyz;
    // feedback is empty on the first frame / after reset -> start from the tube
    if (length(p) < 1e-4) p = seed.xyz;

    float rad = length(p);

    // noise flow, stronger far from the sphere surface
    vec3 f = flow(p * uSphere.z + vec3(0.0, 0.0, t * 0.15));
    p += f * uMotion.x * (0.25 + 0.75 * abs(rad - uSphere.x));

    // slow global spin
    float a = uMotion.z * 0.02;
    p.xz = mat2(cos(a), -sin(a), sin(a), cos(a)) * p.xz;

    // pull onto the sphere surface, radius breathes per particle
    float target = uSphere.x + sin(t * 0.7 + rnd * 6.2831853) * uMotion.y;
    vec3 n = p / max(length(p), 1e-5);
    p = mix(p, n * target, uSphere.y);

    fragColor = TDOutputSwizzle(vec4(p, rnd));
}

out vec4 fragColor;

uniform vec4 uSeed;   // x = radius of the start tube, y = height of the tube

float hash21(vec2 p){
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453123);
}

void main(){
    vec2 uv = vUV.st;
    float a = hash21(uv);
    float b = hash21(uv + vec2(0.371, 0.113));
    float c = hash21(uv + vec2(0.719, 0.537));

    float ang = a * 6.2831853;
    float h = (b - 0.5) * uSeed.y;
    vec3 p = vec3(cos(ang) * uSeed.x, h, sin(ang) * uSeed.x);

    // xyz = seed position inside the tube, w = per particle random (phase / life)
    fragColor = TDOutputSwizzle(vec4(p, c));
}
